def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    topmost_carpet = -1

    for i in range(n):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            topmost_carpet = i + 1

    return topmost_carpet

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid to store the values
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Fill the DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[i][j][0] = grid[i][j]
                dp[i][j][1] = grid[i][j]
            elif i == 0:
                dp[i][j][0] = dp[i][j-1][0] + grid[i][j]
                dp[i][j][1] = dp[i][j-1][1] + grid[i][j]
            elif j == 0:
                dp[i][j][0] = dp[i-1][j][0] + grid[i][j]
                dp[i][j][1] = dp[i-1][j][1] + grid[i][j]
            else:
                dp[i][j][0] = max(dp[i-1][j][0], dp[i][j-1][0]) + grid[i][j]
                dp[i][j][1] = max(dp[i-1][j][1], dp[i][j-1][1]) + grid[i][j]

    # The maximum sum of values collected on the two paths
    return max(dp[N-1][N-1])

