def count_passing_ways(n: int, m: int) -> int:
    if n == 1:
        return 1

    dp = [[0] * (m + 1) for _ in range(n)]

    for i in range(n):
        dp[i][0] = 1

    for j in range(1, m + 1):
        for i in range(n):
            dp[i][j] = dp[(i - 1) % n][j - 1] + dp[(i + 1) % n][j - 1]

    return dp[0][m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 2D list to store the maximum happiness values
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Iterate over each item
    for i in range(1, m + 1):
        price, importance = items[i - 1]
        # Iterate over each possible budget
        for j in range(n + 1):
            if j >= price:
                # Choose the maximum between not taking the item or taking the item
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - price] + importance)
            else:
                # If the budget is not enough, do not take the item
                dp[i][j] = dp[i - 1][j]

    # The maximum happiness value is stored in dp[m][n]
    return dp[m][n]

def max_energy(beads):
    n = len(beads)
    beads = beads + beads  # Duplicate the list to handle the circular nature
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = max(dp[i][k] + dp[k + 1][j] + beads[i] * beads[k] * beads[j] for k in range(i, j))

    return dp[0][n - 1]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n, -1, -1):
        coeff = coeffs[n - i]
        if coeff == 0:
            continue
        if i == 0:
            term = str(abs(coeff))
        elif i == 1:
            if abs(coeff) == 1:
                term = 'x' if coeff == 1 else '-x'
            else:
                term = f'{abs(coeff)}x'
        else:
            if abs(coeff) == 1:
                term = f'x^{i}' if coeff == 1 else f'-x^{i}'
            else:
                term = f'{abs(coeff)}x^{i}'
        if coeff < 0:
            term = '-' + term
        terms.append(term)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping and mapping[e] != o:
            return "Failed"
        mapping[e] = o

    if len(mapping) != len(set(mapping.values())):
        return "Failed"

    decoded_message = ''.join(mapping.get(c, c) for c in message)
    return decoded_message

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1
    return count_partitions(n - k * x, k - 1, x) + count_partitions(n - x, k, x + 1)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest common divisor (GCD)
    and y0 as their least common multiple (LCM).

    Args:
    x0 (int): The GCD that each pair (P, Q) must have.
    y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
    int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    if x0 * x0 > y0:
        return 0

    count = 0
    quotient = y0 // x0

    for a in range(1, quotient + 1):
        if quotient % a == 0:
            b = quotient // a
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2

    return count

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Args:
    num (int): The integer to check for primality.

    Returns:
    bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Filter out statements about the day of the week
    filtered_statements = {participant: [stmt for stmt in stmts if not stmt.startswith("Today is")] for participant, stmts in statements.items()}

    # Check each participant's statements
    for participant, stmts in filtered_statements.items():
        if participant == scenario:
            # If the participant is the scenario, they should be telling the truth
            if any(stmt.startswith("I am guilty.") for stmt in stmts):
                return False
            if any(stmt.startswith("I am not guilty.") for stmt in stmts):
                return True
        else:
            # If the participant is not the scenario, they should be lying
            if participant in liar_count:
                if any(stmt.startswith("I am guilty.") for stmt in stmts):
                    return True
                if any(stmt.startswith("I am not guilty.") for stmt in stmts):
                    return False
            else:
                if any(stmt.startswith("I am guilty.") for stmt in stmts):
                    return False
                if any(stmt.startswith("I am not guilty.") for stmt in stmts):
                    return True

    return True

def calculate_score(system: int, points: str) -> list:
    scores = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        if player_score >= system or opponent_score >= system:
            if abs(player_score - opponent_score) >= 2:
                scores.append(f"{player_score}:{opponent_score}")
                player_score = 0
                opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    # Initialize the list to store Catalan numbers
    catalan = [0] * (n + 1)
    catalan[0] = 1  # Base case: C(0) = 1

    # Compute the Catalan numbers using dynamic programming
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array to store the maximum volume that can be occupied
    dp = [0] * (V + 1)

    # Iterate over each item
    for i in range(n):
        # Update the DP array from the back to avoid using the same item multiple times
        for v in range(V, volumes[i] - 1, -1):
            dp[v] = max(dp[v], dp[v - volumes[i]] + volumes[i])

    # The minimum remaining space is the difference between the box's total capacity and the maximum occupied volume
    return V - dp[V]

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # Initialize a DP table where dp[i][j] represents the number of ways to arrange j pots using the first i types of flowers
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There's one way to arrange 0 pots with 0 types of flowers
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(min(j, a[i - 1]) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def find_most_unhappy_day(schedule) -> int:
    max_unhappiness = 0
    most_unhappy_day = 0

    for day, (school_hours, extra_hours) in enumerate(schedule, start=1):
        total_hours = school_hours + extra_hours
        if total_hours > 8:
            unhappiness = total_hours - 8
            if unhappiness > max_unhappiness:
                max_unhappiness = unhappiness
                most_unhappy_day = day

    return most_unhappy_day

